import Paper, { type PaperProps } from '@mui/material/Paper';
import type { SxProps, Theme } from '@mui/material/styles';
import { mergeSx } from 'merge-sx';
import { forwardRef } from 'react';

const menuPaperSx: SxProps<Theme> = {
  borderRadius: '8px',
  border: '1px solid',
  borderColor: 'divider',
  color: 'text.primary',
  backgroundImage: 'none',
  backgroundColor: 'background.paper',
  boxShadow: '0 8px 24px #2f2b431a',
};
export const menuItemSx: SxProps<Theme> = {
  fontSize: 14,
  lineHeight: '20px',
  padding: '8px 16px',
};

export const MenuPaper = forwardRef<HTMLDivElement, PaperProps>(
  function MenuPaper({ sx, ...props }, ref) {
    return <Paper {...props} ref={ref} sx={mergeSx(menuPaperSx, sx)} />;
  }
);
